package fr.elementa.mine; import org.bukkit.*; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import java.util.*;
public final class MineUpgradeGui { public static final int SLOT=13; public static Inventory build(ElementaMine p,MineRegion m){MineUpgradeHolder h=new MineUpgradeHolder();Inventory i=Bukkit.createInventory(h,27,ChatColor.DARK_AQUA+"Upgrade de la mine");h.setInventory(i);int t=m.getTier();ItemStack x=new ItemStack(t>=MineTiers.MAX_TIER?Material.BEDROCK:Material.DIAMOND);ItemMeta z=x.getItemMeta();z.setDisplayName(ChatColor.AQUA+"Mine tier "+t+" ("+MineTiers.size(p,t)+"x"+MineTiers.size(p,t)+"x"+MineTiers.size(p,t)+")");List<String> l=new ArrayList<>();if(t>=MineTiers.MAX_TIER)l.add(ChatColor.YELLOW+"Niveau maximum atteint");else{l.add(ChatColor.GRAY+"Prochain tier : "+(t+1));l.add(ChatColor.GRAY+"Prix : "+MineTiers.price(p,t+1));l.add(ChatColor.GREEN+"Clique pour confirmer l'achat");}z.setLore(l);x.setItemMeta(z);i.setItem(SLOT,x);return i;}private MineUpgradeGui(){} }
